  // Explicitly defined virtual function
class Base {
public:
  virtual void draw() { std::cout << "Base::draw()" << std::endl; }
};

// Implicitly defined virtual function (compiler generates the vtable entry)
class Derived : public Base {
public:
  // Inherited, implicitly defined virtual function
};

class Derived2 : public Base {
public:
    virtual void draw() override { std::cout << "Derived2::draw()" << std::endl; }
};
